-- Paket ABT "abt-identitas-pihak-1nov" (1 Nov 2026, agen V; keputusan pengguna 101 dan 102): format identitas pihak putusan/penetapan = blangko acuan "[01] [Kabul Verstek] Cerai (Format Lengkap)".
-- Variabel 7047, 7048 dan fungsi isian_rtf_pihak_identitas, isian_rtf_pihak_tambahan diubah; blangko RTF lewat daftar-tambal.tsv/tambal.tsv. Hanya pengguna derry_briantono. Prasyarat: paket ke-30 (perbaikan-1nov) terpasang.
-- PULIH (deterministik): variabel dikembalikan dari tabel sementara pu_lama (dibuat pulih-satker.sh dari cadangan/abt_variabel-sebelum.sql) HANYA bila isinya masih isi BARU paket dan baris cadangan masih isi LAMA yang diharapkan.
-- Dua fungsi dikembalikan oleh pulih-satker.sh (-FUNGSI-LAMA.sql) SESUDAH ini.
START TRANSACTION;
UPDATE abt_variabel a JOIN pu_lama l ON l.no_var=a.no_var SET a.nama=l.nama, a.data_type=l.data_type, a.data_tabel=l.data_tabel, a.data_kolom=l.data_kolom, a.urutan_data=l.urutan_data, a.referensi=l.referensi, a.sql_query=l.sql_query, a.default_data=l.default_data, a.multi_sidang=l.multi_sidang, a.locked=l.locked, a.modifier=l.modifier, a.modified=l.modified WHERE (a.no_var=7047 AND MD5(a.nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND a.data_type='data_sql' AND MD5(a.sql_query)='94f40d4f4bd51b9fab75184521617176') AND (l.no_var=7047 AND MD5(l.nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND l.data_type='data_sql' AND MD5(l.sql_query)='e301c4feae2efcb0794fdff285d8f155');
UPDATE abt_variabel a JOIN pu_lama l ON l.no_var=a.no_var SET a.nama=l.nama, a.data_type=l.data_type, a.data_tabel=l.data_tabel, a.data_kolom=l.data_kolom, a.urutan_data=l.urutan_data, a.referensi=l.referensi, a.sql_query=l.sql_query, a.default_data=l.default_data, a.multi_sidang=l.multi_sidang, a.locked=l.locked, a.modifier=l.modifier, a.modified=l.modified WHERE (a.no_var=7048 AND MD5(a.nama)='0d46332b5be50992e27dfcebf6ec1de4' AND a.data_type='data_sql' AND MD5(a.sql_query)='0424f2f0336893a1b4080e660d707361') AND (l.no_var=7048 AND MD5(l.nama)='0d46332b5be50992e27dfcebf6ec1de4' AND l.data_type='data_sql' AND MD5(l.sql_query)='f9552a7f198356fd6394e7c212bdfc37');
COMMIT;
SELECT IF((SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=7047 AND MD5(nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND data_type='data_sql' AND MD5(sql_query)='e301c4feae2efcb0794fdff285d8f155') OR (no_var=7048 AND MD5(nama)='0d46332b5be50992e27dfcebf6ec1de4' AND data_type='data_sql' AND MD5(sql_query)='f9552a7f198356fd6394e7c212bdfc37'))) = 2, 'VARIABEL KEMBALI', CONCAT('PULIH TIDAK LENGKAP - baris diubah yang sudah kembali ', (SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=7047 AND MD5(nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND data_type='data_sql' AND MD5(sql_query)='e301c4feae2efcb0794fdff285d8f155') OR (no_var=7048 AND MD5(nama)='0d46332b5be50992e27dfcebf6ec1de4' AND data_type='data_sql' AND MD5(sql_query)='f9552a7f198356fd6394e7c212bdfc37'))), ' dari 2 (diubah orang sesudah dipasang? dibiarkan)')) AS hasil;
